template<typename L, typename R>
struct AddExpr {
    const L& l, r;
    auto operator[](size_t i) const { return l[i] + r[i]; }
};

class Vector {
    int storage[10];
public:
    int operator[](size_t i) const { return storage[i]; }

    // Returns expression proxy, defers calculation
    template<typename R>
    AddExpr<Vector, R> operator+(const R& rhs) const {
        return AddExpr<Vector, R>{*this, rhs};
    }
};

// Vector V1, V2;
// AddExpr V_expr = V1 + V2; 
// Loop uses V_expr[i] to execute fused addition.
